277	        send(method: "claude.transcript", params: params) { [weak self] result in
278	            guard let self else { return }
279	            self.claudeTranscriptLoading.remove(surfaceID)
280	            let text = (result["text"] as? String).map(Self.trimTerminalText) ?? ""
281	            let sessionID = result["session_id"] as? String ?? ""
282	            // Diagnostic: the surface we asked for vs the session the bridge
283	            // resolved it to. If these ever look mismatched, this line names the
284	            // exact ids to chase (the bridge maps surface → resume_binding →
285	            // <checkpoint_id>.jsonl and echoes the resolved session_id back).
286	            print("[Transcript] surface=\(surfaceID) -> session=\(sessionID) (\(text.count) chars)")
287	            self.claudeTranscriptSession[surfaceID] = sessionID
288	            self.claudeTranscript[surfaceID] = text
289	        }
290	    }
291	
292	    /// Trim trailing whitespace per line and remove blank trailing lines.
293	    nonisolated private static func trimTerminalText(_ text: String) -> String {
294	        text
295	            .split(separator: "\n", omittingEmptySubsequences: false)
296	            .map { $0.replacingOccurrences(of: "\\s+$", with: "", options: .regularExpression) }
297	            .joined(separator: "\n")
298	            .replacingOccurrences(of: "\\n+$", with: "", options: .regularExpression)
299	    }
300	
301	    /// Bound history so a very long session doesn't produce an attributed
302	    /// string UITextView can't lay out interactively.
303	    nonisolated private static let maxHistoryLines = 5000
304	
305	    nonisolated private static func capHistoryLines(_ text: String) -> String {
306	        let lines = text.split(separator: "\n", omittingEmptySubsequences: false)
307	        guard lines.count > maxHistoryLines else { return text }
308	        return lines.suffix(maxHistoryLines).joined(separator: "\n")
309	    }
310	
311	    func readBrowserURL(_ surfaceID: String) {
312	        send(method: "browser.url.get", params: ["surface_id": surfaceID]) { [weak self] result in
313	            if let url = result["url"] as? String {
314	                self?.browserURLs[surfaceID] = url
315	            }
316	        }
317	    }
318	
319	    func createWorkspace(name: String? = nil) {
320	        var params: [String: Any] = [:]
321	        if let name { params["name"] = name }
322	        send(method: "workspace.create", params: params) { [weak self] _ in
323	            self?.refreshWorkspaces()
324	            self?.refreshSurfaces()
325	        }
326	    }
327	
328	    func closeWorkspace(_ id: String) {
329	        send(method: "workspace.close", params: ["workspace_id": id]) { [weak self] _ in
330	            self?.lastFocusedSurface.removeValue(forKey: id)
331	            // Select the next workspace only after the list is refreshed —
332	            // otherwise `workspaces` still contains the just-closed one.
333	            self?.refreshWorkspaces {
334	                guard let self, self.currentWorkspaceID == id else { return }
335	                if let next = self.workspaces.first(where: { $0.id != id }) {
336	                    self.selectWorkspace(next.id)
337	                }
338	            }
339	        }
340	    }
341	
342	    func splitSurface(direction: String, surfaceID: String? = nil) {
343	        let previousIDs = Set(surfaces.map(\.id))
344	        var params: [String: Any] = ["direction": direction]
345	        if let surfaceID { params["surface_id"] = surfaceID }
346	        send(method: "surface.split", params: params) { [weak self] _ in
347	            self?.refreshSurfacesAndFocusNew(previousIDs: previousIDs)
348	        }
349	    }
350	
351	    func createSurface(type: String = "terminal") {
352	        let previousIDs = Set(surfaces.map(\.id))
353	        send(method: "surface.create", params: ["type": type]) { [weak self] _ in
354	            self?.refreshSurfacesAndFocusNew(previousIDs: previousIDs)
355	        }
356	    }
357	
358	    func closeSurface(_ surfaceID: String) {
359	        send(method: "surface.close", params: ["surface_id": surfaceID]) { [weak self] _ in
360	            self?.refreshSurfaces()
361	        }
362	    }
363	
364	    func clearNotifications() {
365	        send(method: "notification.clear", params: [:]) { [weak self] _ in
366	            self?.notifications = []
367	        }
368	    }
369	
370	    func refreshWorkspaces(then completion: (() -> Void)? = nil) {
371	        // Both list + current must land before firing `completion`, otherwise
372	        // follow-up work (refreshSurfaces) can run against an empty workspace
373	        // list or an unset current ID depending on which reply arrives first.
374	        // Both callbacks run on the main actor, so `pending` needs no locking.
375	        var pending = 2
376	        let step = {
377	            pending -= 1
378	            if pending == 0 { completion?() }
379	        }
380	        send(method: "workspace.list", params: [:]) { [weak self] result in
381	            if let list = result["workspaces"] as? [[String: Any]] {
382	                self?.workspaces = list.compactMap(Workspace.init)
383	            }
384	            step()
385	        }
386	        send(method: "workspace.current", params: [:]) { [weak self] result in
387	            if let id = result["id"] as? String { self?.currentWorkspaceID = id }
388	            step()
389	        }
390	    }
391	
392	    func refreshSurfaces(workspaceID: String? = nil) {
393	        var params: [String: Any] = [:]
394	        if let id = workspaceID ?? currentWorkspaceID {
395	            params["workspace_id"] = id
396	        }
397	        send(method: "surface.list", params: params) { [weak self] result in
398	            if let list = result["surfaces"] as? [[String: Any]] {
399	                self?.surfaces = list.compactMap(Surface.init)
400	                // Validate remembered surface still exists
401	                if let localID = self?.localFocusedSurfaceID,
402	                   self?.surfaces.contains(where: { $0.id == localID }) == false {
403	                    self?.localFocusedSurfaceID = nil
404	                }
405	                // Auto-select first surface if nothing is focused
406	                if self?.focusedSurfaceID == nil, let first = self?.surfaces.first {
407	                    self?.localFocusedSurfaceID = first.id
408	                }
409	            }
410	        }
411	    }
412	
413	    private func refreshSurfacesAndFocusNew(previousIDs: Set<String>) {
414	        var params: [String: Any] = [:]
415	        if let id = currentWorkspaceID {
416	            params["workspace_id"] = id
417	        }
418	        send(method: "surface.list", params: params) { [weak self] result in
419	            guard let self else { return }
420	            if let list = result["surfaces"] as? [[String: Any]] {
421	                self.surfaces = list.compactMap(Surface.init)
422	                if let newSurface = self.surfaces.first(where: { !previousIDs.contains($0.id) }) {
423	                    self.focusSurface(newSurface.id)
424	                } else if self.focusedSurfaceID == nil, let first = self.surfaces.first {
425	                    self.localFocusedSurfaceID = first.id
426	                }
427	            }
428	        }
429	    }
430	
431	    func refreshPanes() {
432	        var params: [String: Any] = [:]
433	        if let id = currentWorkspaceID {
434	            params["workspace_id"] = id
435	        }
436	        send(method: "pane.list", params: params) { [weak self] result in
437	            if let list = result["panes"] as? [[String: Any]] {
438	                self?.panes = list.compactMap(Pane.init)
439	            }
440	        }
441	    }
442	
443	    // MARK: - Helpers
444	
445	    var focusedSurfaceID: String? {
446	        // Prefer pane-derived focus, then surface.is_focused, then local tracking
447	        panes.first(where: { $0.isFocused })?.focusedSurfaceID
448	            ?? surfaces.first(where: { $0.isFocused })?.id
449	            ?? localFocusedSurfaceID
450	    }
451	
452	    var currentWorkspaceSurfaces: [Surface] {
453	        guard let wsID = currentWorkspaceID else { return surfaces }
454	        return surfaces.filter { $0.workspaceID == wsID }
455	    }
456	
457	    func surfaceTitle(for id: String) -> String {
458	        surfaces.first(where: { $0.id == id })?.title ?? ""
459	    }
460	
461	    func hasNotification(for pane: Pane) -> Bool {
462	        notifications.contains { n in
463	            guard let sid = n.surfaceID else { return false }
464	            return pane.surfaceIDs.contains(sid)
465	        }
466	    }
467	
468	    func hasNotification(for surface: Surface) -> Bool {
469	        notifications.contains { $0.surfaceID == surface.id }
470	    }
471	
472	    func clearNotificationsForFocusedSurface() {
473	        guard let focusedID = focusedSurfaceID else { return }
474	        notifications.removeAll { $0.surfaceID == focusedID }
475	    }
476	
477	    // MARK: - Private helpers
478	
479	    private func send(
480	        method: String,
481	        params: [String: Any],
482	        completion: (([String: Any]) -> Void)? = nil
483	    ) {
484	        client?.send(method: method, params: params, completion: completion)
485	    }
486	}
487	
488	// MARK: - BridgeClientDelegate
489	
490	extension AppState: BridgeClientDelegate {
491	    func clientDidConnect(_ client: BridgeClient) {
492	        connectionStatus = .connected
493	        refreshWorkspaces {
494	            self.refreshSurfaces()
495	            self.refreshPanes()
496	        }
497	    }
498	
499	    func clientDidDisconnect(_ client: BridgeClient, error: Error?) {
500	        connectionStatus = .reconnecting
501	        // In-flight transcript RPCs will never complete now; clear their loading
502	        // flags so the history viewer doesn't hang on a spinner.
503	        claudeTranscriptLoading.removeAll()
504	    }
505	
506	    func clientDidReceiveMessage(_ client: BridgeClient, message: BridgeMessage) {
507	        switch message {
508	        case .connected(let payload):
509	            connectionStatus = .connected(cmuxConnected: payload.cmuxConnected)
510	        case .notificationCreated(let n):
511	            notifications.insert(n, at: 0)
512	            print("[Notification] id=\(n.id) surfaceID=\(n.surfaceID ?? "nil") workspaceID=\(n.workspaceID ?? "nil") title=\(n.title)")
513	            print("[Notification] surface IDs: \(surfaces.map(\.id))")
514	            scheduleLocalNotification(n)
515	        case .notificationCleared:
516	            notifications = []
517	        case .cmuxConnected:
518	            connectionStatus = .connected(cmuxConnected: true)
519	            refreshWorkspaces {
520	                self.refreshSurfaces()
521	                self.refreshPanes()
522	            }
523	        case .cmuxDisconnected:
524	            connectionStatus = .connected(cmuxConnected: false)
525	            panes = []
526	        case .commandResponse:
527	            break
528	        }
529	    }
530	}
531	
532	// MARK: - BridgeDiscoveryDelegate
533	
534	extension AppState: BridgeDiscoveryDelegate {
535	    func discovery(_ discovery: BridgeDiscovery, didFind candidates: [PairingCredentials]) {
536	        guard connectionStatus == .disconnected,
537	              let stored = try? pairingStore.load() else { return }
538	        if let match = candidates.first(where: { $0.host == stored.host && $0.port == stored.port }) {
539	            connect(to: PairingCredentials(host: match.host, port: match.port, token: stored.token, tailscaleHost: stored.tailscaleHost))
540	        }
541	    }
542	}
543	
544	// MARK: - Models
545	
546	struct BridgeNotification: Identifiable, Decodable {
547	    let id: String
548	    let title: String
549	    let subtitle: String?
550	    let body: String?
551	    let workspaceID: String?
552	    let surfaceID: String?
553	    let isRead: Bool?
554	
555	    enum CodingKeys: String, CodingKey {
556	        case id, title, subtitle, body
557	        case workspaceID = "workspace_id"
558	        case surfaceID = "surface_id"
559	        case isRead = "is_read"
560	    }
561	}
562	
563	struct Workspace: Identifiable {
564	    let id: String
565	    let name: String
566	
567	    init?(_ dict: [String: Any]) {
568	        guard let id = dict["id"] as? String else { return nil }
569	        self.id = id
570	        self.name = (dict["name"] as? String) ?? id
571	    }
572	}
573	
574	struct Surface: Identifiable {
575	    let id: String
576	    let title: String
577	    let type: String
578	    let workspaceID: String?
579	    let isFocused: Bool
580	    /// Agent kind from cmux's resume_binding (e.g. "claude"), when this surface
581	    /// is running an agent. Used to offer conversation-transcript history.
582	    let agentKind: String?
583	
584	    var isBrowser: Bool { type == "browser" }
585	    var isClaudeAgent: Bool { agentKind == "claude" }
586	
587	    init?(_ dict: [String: Any]) {
588	        guard let id = dict["id"] as? String else { return nil }
589	        self.id = id
590	        self.type = (dict["type"] as? String) ?? "terminal"
591	        self.title = (dict["title"] as? String) ?? self.type
592	        self.workspaceID = dict["workspace_id"] as? String
593	        self.isFocused = dict["is_focused"] as? Bool ?? false
594	        self.agentKind = (dict["resume_binding"] as? [String: Any])?["kind"] as? String
595	    }
596	}
597	
598	struct Pane: Identifiable {
599	    let id: String
600	    let pixelFrame: CGRect
601	    let containerFrame: CGSize
602	    let surfaceIDs: [String]
603	    let focusedSurfaceID: String?
604	    let isFocused: Bool
605	
606	    var normalizedFrame: CGRect {
607	        guard containerFrame.width > 0, containerFrame.height > 0 else {
608	            return CGRect(x: 0, y: 0, width: 1, height: 1)
609	        }
610	        return CGRect(
611	            x: pixelFrame.origin.x / containerFrame.width,
612	            y: pixelFrame.origin.y / containerFrame.height,
613	            width: pixelFrame.size.width / containerFrame.width,
614	            height: pixelFrame.size.height / containerFrame.height
615	        )
616	    }
617	
618	    init?(_ dict: [String: Any]) {
619	        guard let id = dict["id"] as? String else { return nil }
620	        self.id = id
621	
622	        if let pf = dict["pixel_frame"] as? [String: Any] {
623	            let x = (pf["x"] as? Double).map { CGFloat($0) } ?? 0
624	            let y = (pf["y"] as? Double).map { CGFloat($0) } ?? 0
625	            let w = (pf["width"] as? Double).map { CGFloat($0) } ?? 100
626	            let h = (pf["height"] as? Double).map { CGFloat($0) } ?? 100
627	            pixelFrame = CGRect(x: x, y: y, width: w, height: h)
628	        } else {
629	            pixelFrame = CGRect(x: 0, y: 0, width: 100, height: 100)
630	        }
631	
632	        if let cf = dict["container_frame"] as? [String: Any] {
633	            let w = (cf["width"] as? Double).map { CGFloat($0) } ?? 100
634	            let h = (cf["height"] as? Double).map { CGFloat($0) } ?? 100
635	            containerFrame = CGSize(width: w, height: h)
636	        } else {
637	            containerFrame = CGSize(width: 100, height: 100)
638	        }
639	
640	        surfaceIDs = dict["surface_ids"] as? [String] ?? []
641	        focusedSurfaceID = dict["focused_surface_id"] as? String
642	        isFocused = dict["is_focused"] as? Bool ?? false
643	    }
644	}
645	
646	enum ConnectionStatus: Equatable {
647	    case disconnected
648	    case connecting
649	    case reconnecting
650	    case connected(cmuxConnected: Bool = true)
651	
652	    static var connected: ConnectionStatus { .connected(cmuxConnected: true) }
653	
654	    var isConnected: Bool {
655	        if case .connected = self { return true }
656	        return false
657	    }
658	
659	    var label: String {
660	        switch self {
661	        case .disconnected: return "Disconnected"
662	        case .connecting: return "Connecting…"
663	        case .reconnecting: return "Reconnecting…"
664	        case .connected(let cmux):
665	            return cmux ? "Connected" : "Bridge connected (cmux offline)"
666	        }
667	    }
668	
669	    var color: String {
670	        switch self {
671	        case .connected(true): return "green"
672	        case .connected(false): return "yellow"
673	        case .reconnecting: return "yellow"
674	        case .connecting: return "yellow"
675	        case .disconnected: return "red"
676	        }
677	    }
678	}
