import SwiftUI

struct ConnectionStatusBar: View {
    @EnvironmentObject var appState: AppState

    private var isVisible: Bool {
        switch appState.connectionStatus {
        case .connected(true): return false
        default: return true
        }
    }

    var body: some View {
        if isVisible {
            HStack(spacing: 6) {
                if case .reconnecting = appState.connectionStatus {
                    ProgressView().scaleEffect(0.7)
                } else {
                    Circle()
                        .fill(statusColor)
                        .frame(width: 8, height: 8)
                }
                Text(appState.connectionStatus.label)
                    .font(.caption)
                    .foregroundStyle(.primary)
            }
            .padding(.horizontal, 12)
            .padding(.vertical, 6)
            .background(.regularMaterial, in: Capsule())
            .padding(.top, 4)
            .transition(.move(edge: .top).combined(with: .opacity))
            .animation(.easeInOut, value: appState.connectionStatus)
        }
    }

    private var statusColor: Color {
        switch appState.connectionStatus {
        case .connected(true): return .green
        case .connected(false): return .yellow
        case .reconnecting, .connecting: return .yellow
        case .disconnected: return .red
        }
    }
}

import SwiftUI

struct MainTabView: View {
    @EnvironmentObject var appState: AppState
    @State private var showSidebar = false
    @State private var sidebarTimer: Timer?
    @State private var selectedTab: SidebarTab = .layout

    var body: some View {
        ZStack(alignment: .leading) {
            // Full-screen content
            Group {
                switch selectedTab {
                case .layout:
                    WorkspaceLayoutView()
                case .surfaces:
                    SurfaceListView()
                case .send:
                    SendTextView()
                case .notifications:
                    NotificationsView()
                case .settings:
                    SettingsView()
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)

            // Menu toggle button (top-left, visible when sidebar hidden)
            if !showSidebar {
                VStack {
                    HStack {
                        Button { revealSidebar() } label: {
                            Image(systemName: "line.3.horizontal")
                                .font(.system(size: 14, weight: .medium))
                                .foregroundStyle(.white.opacity(0.4))
                                .frame(width: 32, height: 32)
                                .background(
                                    Circle()
                                        .fill(.ultraThinMaterial.opacity(0.5))
                                        .environment(\.colorScheme, .dark)
                                )
                        }
                        .padding(.leading, 12)
                        .padding(.top, 8)
                        Spacer()
                    }
                    Spacer()
                }
                .transition(.opacity)
            }

            // Sidebar overlay
            if showSidebar {
                // Dimmed background
                Color.black.opacity(0.3)
                    .ignoresSafeArea()
                    .onTapGesture { dismissSidebar() }
                    .transition(.opacity)

                // Sidebar panel
                sidebarPanel
                    .transition(.move(edge: .leading).combined(with: .opacity))
            }
        }
        .animation(.spring(response: 0.3, dampingFraction: 0.85), value: showSidebar)
        .onDisappear {
            // Otherwise the auto-dismiss timer fires into a torn-down view.
            sidebarTimer?.invalidate()
            sidebarTimer = nil
        }
        .overlay(alignment: .top) {
            ConnectionStatusBar()
        }
        .sheet(isPresented: $appState.isPairingPresented) {
            PairingView()
        }
        .alert(
            "Replace pairing?",
            isPresented: Binding(
                get: { appState.pendingPairing != nil },
                set: { if !$0 { appState.cancelPendingPairing() } }
            ),
            presenting: appState.pendingPairing
        ) { pending in
            Button("Pair with \(pending.host):\(pending.port)", role: .destructive) {
                appState.confirmPendingPairing()
            }
            Button("Cancel", role: .cancel) {
                appState.cancelPendingPairing()
            }
        } message: { pending in
            Text("This will disconnect from your current bridge and send all input to \(pending.host):\(pending.port). Only continue if you initiated this pairing.")
        }
    }

    // MARK: - Sidebar

    private var sidebarPanel: some View {
        VStack(alignment: .leading, spacing: 2) {
            ForEach(SidebarTab.allCases) { tab in
                Button {
                    selectedTab = tab
                    dismissSidebar()
                } label: {
                    HStack(spacing: 10) {
                        Image(systemName: tab.icon)
                            .font(.system(size: 13))
                            .frame(width: 20)
                        Text(tab.label)
                            .font(.system(size: 13, weight: .medium, design: .monospaced))
                        Spacer()
                        if tab == .notifications && appState.notifications.count > 0 {
                            Text("\(appState.notifications.count)")
                                .font(.system(size: 10, weight: .bold, design: .monospaced))
                                .foregroundStyle(.black)
                                .padding(.horizontal, 6)
                                .padding(.vertical, 2)
                                .background(Capsule().fill(.orange))
                        }
                    }
                    .foregroundStyle(selectedTab == tab ? .white : .white.opacity(0.5))
                    .padding(.horizontal, 16)
                    .padding(.vertical, 10)
                    .background(
                        RoundedRectangle(cornerRadius: 8)
                            .fill(selectedTab == tab ? Color.white.opacity(0.1) : .clear)
                    )
                }
                .buttonStyle(.plain)
            }

            Spacer()

            // Version / branding
            Text("cmux companion")
                .font(.system(size: 10, weight: .regular, design: .monospaced))
                .foregroundStyle(.white.opacity(0.2))
                .padding(.horizontal, 16)
                .padding(.bottom, 12)
        }
        .padding(.top, 16)
        .frame(width: 200)
        .frame(maxHeight: .infinity)
        .background(
            Rectangle()
                .fill(.ultraThinMaterial)
                .environment(\.colorScheme, .dark)
        )
        .clipShape(
            UnevenRoundedRectangle(
                topLeadingRadius: 0,
                bottomLeadingRadius: 0,
                bottomTrailingRadius: 16,
                topTrailingRadius: 16
            )
        )
    }

    // MARK: - Actions

    private func revealSidebar() {
        showSidebar = true
        sidebarTimer?.invalidate()
        sidebarTimer = Timer.scheduledTimer(withTimeInterval: 4, repeats: false) { _ in
            Task { @MainActor in
                dismissSidebar()
            }
        }
    }

    private func dismissSidebar() {
        showSidebar = false
        sidebarTimer?.invalidate()
        sidebarTimer = nil
    }
}

// MARK: - Tab model

enum SidebarTab: String, CaseIterable, Identifiable {
    case layout
    case surfaces
    case send
    case notifications
    case settings

    var id: String { rawValue }

    var label: String {
        switch self {
        case .layout: return "Layout"
        case .surfaces: return "Surfaces"
        case .send: return "Send"
        case .notifications: return "Alerts"
        case .settings: return "Settings"
        }
    }

    var icon: String {
        switch self {
        case .layout: return "rectangle.3.group.fill"
        case .surfaces: return "square.split.2x1"
        case .send: return "keyboard"
        case .notifications: return "bell"
        case .settings: return "gear"
        }
    }
}

import Foundation

// MARK: - Message types

enum BridgeMessage {
    case connected(ConnectedPayload)
    case notificationCreated(BridgeNotification)
    case notificationCleared
    case cmuxConnected
    case cmuxDisconnected
    case commandResponse(CommandResponse)
}

struct ConnectedPayload: Decodable {
    let bridgeVersion: String
    let cmuxConnected: Bool
    let protocolVersion: Int

    enum CodingKeys: String, CodingKey {
        case bridgeVersion = "bridge_version"
        case cmuxConnected = "cmux_connected"
        case protocolVersion = "protocol_version"
    }
}

struct CommandResponse {
    let id: String
    let ok: Bool
    let result: [String: Any]
    let error: CommandError?
}

struct CommandError {
    let code: String
    let message: String
}

// MARK: - Delegate

protocol BridgeClientDelegate: AnyObject {
    @MainActor func clientDidConnect(_ client: BridgeClient)
    @MainActor func clientDidDisconnect(_ client: BridgeClient, error: Error?)
    @MainActor func clientDidReceiveMessage(_ client: BridgeClient, message: BridgeMessage)
}

// MARK: - Client

final class BridgeClient: NSObject {
    let credentials: PairingCredentials
    weak var delegate: BridgeClientDelegate?

    private var task: URLSessionWebSocketTask?
    private var session: URLSession?
    private var completions: [String: ([String: Any]) -> Void] = [:]
    // `completions` is written from the caller (main actor) and read from the
    // URLSession receive queue, so all access must be serialized.
    private let completionsLock = NSLock()
    private var reconnectTask: Task<Void, Never>?
    private var shouldReconnect = true
    private var backoff: TimeInterval = 1

    init(credentials: PairingCredentials) {
        self.credentials = credentials
    }

    // MARK: - Public API

    func connect() {
        shouldReconnect = true
        startConnection()
    }

    func disconnect() {
        shouldReconnect = false
        reconnectTask?.cancel()
        task?.cancel(with: .normalClosure, reason: nil)
        task = nil
        // URLSession strongly retains its delegate (self) until invalidated —
        // without this every connect leaks a BridgeClient.
        session?.invalidateAndCancel()
        session = nil
    }

    func send(
        method: String,
        params: [String: Any],
        completion: (([String: Any]) -> Void)? = nil
    ) {
        let id = UUID().uuidString
        let payload: [String: Any] = ["id": id, "method": method, "params": params]

        // Serialize the payload and confirm we have a live socket *before*
        // registering the completion, so a failed send can't leak a callback
        // that will never fire.
        guard let data = try? JSONSerialization.data(withJSONObject: payload),
              let text = String(data: data, encoding: .utf8),
              let task else { return }

        if let completion {
            completionsLock.lock()
            completions[id] = completion
            completionsLock.unlock()
        }

        task.send(.string(text)) { [weak self] error in
            guard error != nil, let self else { return }
            // The send failed — drop the pending completion so callers that
            // chain follow-up work (refreshSurfaces, etc.) aren't stranded.
            self.completionsLock.lock()
            self.completions.removeValue(forKey: id)
            self.completionsLock.unlock()
        }
    }

    // MARK: - Private

    /// Whether to try the tailscale host on next connection attempt.
    private var useTailscale = false

    private func startConnection() {
        // Release the previous session's strong hold on us (its delegate)
        // before spinning up a new one; otherwise each reconnect leaks.
        session?.invalidateAndCancel()

        let host: String
        if useTailscale, let tsHost = credentials.tailscaleHost, !tsHost.isEmpty {
            host = tsHost
        } else {
            host = credentials.host
        }

        let urlString = "ws://\(host):\(credentials.port)/ws"
        guard let url = URL(string: urlString) else { return }

        var request = URLRequest(url: url)
        request.setValue("Bearer \(credentials.token)", forHTTPHeaderField: "Authorization")
        request.timeoutInterval = useTailscale ? 10 : 5

        let session = URLSession(configuration: .default, delegate: self, delegateQueue: nil)
        self.session = session
        let task = session.webSocketTask(with: request)
        // The default receive limit (1 MiB) can be exceeded by large payloads
        // like claude session transcripts; raise it so those frames aren't dropped.
        task.maximumMessageSize = 8 * 1024 * 1024
        completionsLock.lock()
        self.task = task
        completionsLock.unlock()
        task.resume()
        receiveNext()
    }

    private func receiveNext() {
        task?.receive { [weak self] result in
            guard let self else { return }
            switch result {
            case .success(let message):
                self.handleMessage(message)
                self.receiveNext()
            case .failure:
                self.handleDisconnect(error: nil)
            }
        }
    }

    private func handleMessage(_ message: URLSessionWebSocketTask.Message) {
        guard case .string(let text) = message,
              let data = text.data(using: .utf8),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        else { return }

        let bridgeMessage = parse(json: json)
        Task { @MainActor in
            self.delegate?.clientDidReceiveMessage(self, message: bridgeMessage)
        }

        // Dispatch command responses to completions. Fire the completion for
        // ANY response carrying a matching id — even an `ok:true` reply with no
        // `result` payload — otherwise chained follow-up work never runs and
        // the UI silently goes stale.
        if let id = json["id"] as? String {
            completionsLock.lock()
            let completion = completions.removeValue(forKey: id)
            completionsLock.unlock()
            if let completion {
                let result = json["result"] as? [String: Any] ?? [:]
                Task { @MainActor in completion(result) }
            }
        }
    }

    private func parse(json: [String: Any]) -> BridgeMessage {
        let type = json["type"] as? String ?? ""
        let data = json["data"] as? [String: Any] ?? [:]

        switch type {
        case "connected":
            if let payloadData = try? JSONSerialization.data(withJSONObject: data),
               let payload = try? JSONDecoder().decode(ConnectedPayload.self, from: payloadData) {
                return .connected(payload)
            }
        case "notification.created":
            if let notifData = try? JSONSerialization.data(withJSONObject: data),
               let notif = try? JSONDecoder().decode(BridgeNotification.self, from: notifData) {
                return .notificationCreated(notif)
            }
        case "notification.cleared":
            return .notificationCleared
        case "cmux.connected":
            return .cmuxConnected
        case "cmux.disconnected":
            return .cmuxDisconnected
        default:
            break
        }

        // Command response envelope
        if let id = json["id"] as? String {
            let ok = json["ok"] as? Bool ?? false
            let result = json["result"] as? [String: Any] ?? [:]
            var cmdError: CommandError?
            if let errDict = json["error"] as? [String: Any] {
                cmdError = CommandError(
                    code: errDict["code"] as? String ?? "",
                    message: errDict["message"] as? String ?? ""
                )
            }
            return .commandResponse(CommandResponse(id: id, ok: ok, result: result, error: cmdError))
        }

        return .notificationCleared // fallback
    }

    private func handleDisconnect(error: Error?) {
        // A clean server close fires BOTH receiveNext's .failure and the
        // didCloseWith delegate callback. Dedupe under the lock so we don't
        // schedule two reconnects (racing, doubled connections). The lock also
        // guards `task`, which both callbacks race to clear.
        completionsLock.lock()
        guard task != nil else {
            completionsLock.unlock()
            return
        }
        task = nil
        // Drop any in-flight completions; their responses will never arrive.
        // A fresh connect re-issues refreshWorkspaces/Surfaces from scratch.
        completions.removeAll()
        completionsLock.unlock()
        Task { @MainActor in
            self.delegate?.clientDidDisconnect(self, error: error)
        }
        guard shouldReconnect else { return }
        scheduleReconnect()
    }

    private func scheduleReconnect() {
        let delay = backoff
        backoff = min(backoff * 2, 30)

        // Alternate between LAN and Tailscale on each retry
        if credentials.tailscaleHost != nil {
            useTailscale.toggle()
        }

        reconnectTask = Task {
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard !Task.isCancelled, self.shouldReconnect else { return }
            self.startConnection()
        }
    }
}

// MARK: - URLSessionWebSocketDelegate

extension BridgeClient: URLSessionWebSocketDelegate {
    func urlSession(
        _ session: URLSession,
        webSocketTask: URLSessionWebSocketTask,
        didOpenWithProtocol protocol: String?
    ) {
        backoff = 1
        useTailscale = false // Reset — LAN worked, prefer it next time
        Task { @MainActor in
            self.delegate?.clientDidConnect(self)
        }
    }

    func urlSession(
        _ session: URLSession,
        webSocketTask: URLSessionWebSocketTask,
        didCloseWith closeCode: URLSessionWebSocketTask.CloseCode,
        reason: Data?
    ) {
        handleDisconnect(error: nil)
    }
}

