    guard let creds = try? pairingStore.load() else { return }
    connect(to: creds)
}

func connect(to credentials: PairingCredentials) {
    client?.disconnect()
    let newClient = BridgeClient(credentials: credentials)
    newClient.delegate = self
    client = newClient
    newClient.connect()
}

