170	func authenticate(conn net.Conn, password string) error {
171		_ = conn.SetDeadline(time.Now().Add(5 * time.Second))
172		defer func() { _ = conn.SetDeadline(time.Time{}) }()
173	
174		id := randomHex(8)
175		req := map[string]any{
176			"id":     id,
177			"method": "auth.login",
178			"params": map[string]any{"password": password},
179		}
180		payload, _ := json.Marshal(req)
181		if _, err := fmt.Fprintf(conn, "%s\n", payload); err != nil {
182			return fmt.Errorf("send auth.login: %w", err)
183		}
184	
185		reader := bufio.NewReader(conn)
186		line, err := reader.ReadString('\n')
187		if err != nil {
188			return fmt.Errorf("read auth response: %w", err)
189		}
190	
191		var resp struct {
192			OK    bool `json:"ok"`
193			Error *struct {
194				Code    string `json:"code"`
195				Message string `json:"message"`
196			} `json:"error"`
197		}
198		if err := json.Unmarshal([]byte(strings.TrimSpace(line)), &resp); err != nil {
199			return fmt.Errorf("parse auth response: %w", err)
200		}
201		if !resp.OK {
202			if resp.Error != nil {
203				return fmt.Errorf("[%s] %s", resp.Error.Code, resp.Error.Message)
204			}
205			return fmt.Errorf("authentication failed")
206		}
207		return nil
208	}
209	
210	func randomHex(n int) string {
211		b := make([]byte, n)
212		_, _ = rand.Read(b)
213		return hex.EncodeToString(b)
214	}

