1	package socket
2	
3	import (
4		"bufio"
5		"crypto/rand"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"net"
10		"os"
11		"path/filepath"
12		"strings"
13		"sync"
14		"time"
15	)
16	
17	// Client is a persistent connection to the cmux Unix socket.
18	// It serialises all sends with a mutex so callers can share one instance.
19	type Client struct {
20		socketPath string
21		password   string
22	
23		mu     sync.Mutex
24		conn   net.Conn
25		reader *bufio.Reader
26	}
27	
28	func NewClient(socketPath, password string) *Client {
29		return &Client{socketPath: socketPath, password: password}
30	}
31	
32	// Connect establishes (or re-establishes) the connection and authenticates.
33	func (c *Client) Connect() error {
34		c.mu.Lock()
35		defer c.mu.Unlock()
36	
37		if c.conn != nil {
38			c.conn.Close()
39			c.conn = nil
40			c.reader = nil
41		}
42	
43		conn, err := net.Dial("unix", c.socketPath)
44		if err != nil {
45			return fmt.Errorf("connect %s: %w", c.socketPath, err)
46		}
47	
48		if c.password != "" {
49			if err := authenticate(conn, c.password); err != nil {
50				conn.Close()
51				return fmt.Errorf("auth: %w", err)
52			}
53		}
54	
55		c.conn = conn
56		c.reader = bufio.NewReaderSize(conn, 1<<20)
57		return nil
58	}
59	
60	// Close shuts down the underlying connection.
61	func (c *Client) Close() {
62		c.mu.Lock()
63		defer c.mu.Unlock()
64		if c.conn != nil {
65			c.conn.Close()
66			c.conn = nil
67		}
68	}
69	
70	// Send sends a v2 JSON-RPC request and returns the parsed result object.
71	// If the connection is closed it returns an error; the caller is responsible
72	// for reconnecting.
73	func (c *Client) Send(method string, params map[string]any) (json.RawMessage, error) {
74		c.mu.Lock()
75		defer c.mu.Unlock()
76	
77		if c.conn == nil {
78			return nil, fmt.Errorf("not connected")
79		}
80	
81		id := randomHex(8)
82		req := map[string]any{
83			"id":     id,
84			"method": method,
85			"params": params,
86		}
87		if params == nil {
88			req["params"] = map[string]any{}
89		}
90	
91		payload, err := json.Marshal(req)
92		if err != nil {
93			return nil, fmt.Errorf("marshal: %w", err)
94		}
95	
96		_ = c.conn.SetDeadline(time.Now().Add(10 * time.Second))
97		if _, err := fmt.Fprintf(c.conn, "%s\n", payload); err != nil {
98			c.conn = nil
99			c.reader = nil
100			return nil, fmt.Errorf("write: %w", err)
101		}
102	
103		line, err := c.reader.ReadString('\n')
104		if err != nil {
105			c.conn = nil
106			c.reader = nil
107			return nil, fmt.Errorf("read: %w", err)
108		}
109		if len(line) > 8<<20 {
110			c.conn = nil
111			c.reader = nil
112			return nil, fmt.Errorf("response line too large: %d bytes", len(line))
113		}
114		_ = c.conn.SetDeadline(time.Time{})
115	
116		var resp struct {
117			OK     bool            `json:"ok"`
118			Result json.RawMessage `json:"result"`
119			Error  *struct {
120				Code    string `json:"code"`
121				Message string `json:"message"`
122			} `json:"error"`
123		}
124		if err := json.Unmarshal([]byte(strings.TrimSpace(line)), &resp); err != nil {
125			return nil, fmt.Errorf("parse response: %w", err)
126		}
127		if !resp.OK {
128			if resp.Error != nil {
129				return nil, fmt.Errorf("[%s] %s", resp.Error.Code, resp.Error.Message)
130			}
131			return nil, fmt.Errorf("server returned error")
132		}
133		return resp.Result, nil
134	}
135	
136	// DetectSocketPath returns the best available cmux socket path by reading
137	// the last-socket-path file written by the cmux Mac app, with fallbacks.
138	func DetectSocketPath() string {
139		home, err := os.UserHomeDir()
140		if err != nil {
141			return "/tmp/cmux.sock"
142		}
143	
144		appSupport := filepath.Join(home, "Library", "Application Support", "cmux")
145	
146		// Primary: last-socket-path written by cmux on each launch
147		if data, err := os.ReadFile(filepath.Join(appSupport, "last-socket-path")); err == nil {
148			if p := strings.TrimSpace(string(data)); p != "" {
149				return p
150			}
151		}
152	
153		// XDG state directory (cmux v2+)
154		xdgState := filepath.Join(home, ".local", "state", "cmux",
155			fmt.Sprintf("cmux-%d.sock", os.Getuid()))
156		if _, err := os.Stat(xdgState); err == nil {
157			return xdgState
158		}
159	
160		// Stable default (legacy Application Support)
161		stable := filepath.Join(appSupport, "cmux.sock")
162		if _, err := os.Stat(stable); err == nil {
163			return stable
164		}
165	
166		// Legacy fallback
167		return "/tmp/cmux.sock"
168	}
169	
170	func authenticate(conn net.Conn, password string) error {
171		_ = conn.SetDeadline(time.Now().Add(5 * time.Second))
172		defer func() { _ = conn.SetDeadline(time.Time{}) }()
173	
174		id := randomHex(8)
175		req := map[string]any{
176			"id":     id,
177			"method": "auth.login",
178			"params": map[string]any{"password": password},
179		}
180		payload, _ := json.Marshal(req)
181		if _, err := fmt.Fprintf(conn, "%s\n", payload); err != nil {
182			return fmt.Errorf("send auth.login: %w", err)
183		}
184	
185		reader := bufio.NewReader(conn)
186		line, err := reader.ReadString('\n')
187		if err != nil {
188			return fmt.Errorf("read auth response: %w", err)
189		}
190	
191		var resp struct {
192			OK    bool `json:"ok"`
193			Error *struct {
194				Code    string `json:"code"`
195				Message string `json:"message"`
196			} `json:"error"`
197		}
198		if err := json.Unmarshal([]byte(strings.TrimSpace(line)), &resp); err != nil {
199			return fmt.Errorf("parse auth response: %w", err)
200		}
201		if !resp.OK {
202			if resp.Error != nil {
203				return fmt.Errorf("[%s] %s", resp.Error.Code, resp.Error.Message)
204			}
205			return fmt.Errorf("authentication failed")
206		}
207		return nil
208	}
209	
210	func randomHex(n int) string {
211		b := make([]byte, n)
212		_, _ = rand.Read(b)
213		return hex.EncodeToString(b)
214	}

