61	func loadConfig(dir string) (config, error) {
62		cfg := defaultConfig()
63		path := filepath.Join(dir, configFileName)
64		data, err := os.ReadFile(path)
65		if os.IsNotExist(err) {
66			return cfg, nil
67		}
68		if err != nil {
69			return cfg, fmt.Errorf("read config: %w", err)
70		}
71		if err := json.Unmarshal(data, &cfg); err != nil {
72			return cfg, fmt.Errorf("parse config: %w", err)
73		}
74		return cfg, nil
75	}
