77	func saveConfig(dir string, cfg config) error {
78		if err := os.MkdirAll(dir, 0o700); err != nil {
79			return err
80		}
81		data, err := json.MarshalIndent(cfg, "", "  ")
82		if err != nil {
83			return err
84		}
85		return os.WriteFile(filepath.Join(dir, configFileName), append(data, '\n'), 0o600)
86	}
