119	func runPair(dir string, cfg config) {
120		// Prompt for password if not configured
121		if cfg.SocketPassword == "" {
122			fmt.Print("cmux socket password (leave empty if not using password mode): ")
123			var pw string
124			_, _ = fmt.Scanln(&pw)
125			if pw != "" {
126				cfg.SocketPassword = pw
127				if err := saveConfig(dir, cfg); err != nil {
128					log.Printf("warning: could not save config: %v", err)
129				} else {
130					fmt.Println("Password saved to config.")
131				}
132			}
133		}
134	
135		// Verify connectivity
136		client := socket.NewClient(cfg.SocketPath, cfg.SocketPassword)
137		if err := client.Connect(); err != nil {
138			log.Fatalf("cannot connect to cmux socket: %v\nMake sure cmux is running and the socket path is correct (%s)", err, cfg.SocketPath)
139		}
140		client.Close()
141		fmt.Println("Connected to cmux.")
142	
143		token, err := pair.LoadOrCreateToken(dir)
