160	func startTailscaleForPairing(dir string, cfg config) string {
161		ts := &tsnet.Server{
162			Hostname: cfg.TailscaleHostname,
163			Dir:      filepath.Join(dir, "tailscale"),
164		}
165	
166		ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
167		defer cancel()
168	
169		status, err := ts.Up(ctx)
170		if err != nil {
171			log.Printf("tailscale: failed to start: %v", err)
172			ts.Close()
